            continue
        try:
            with Image.open(path) as im:
                side = min(im.size)
        except Exception as exc:
            print(f'READ_FAIL {path}: {exc}')
            continue
        total += 1
        if split in {'train', 'val'} and side < 30:
            low.append((side, path))
        for lo, hi, label in bins:
            if lo <= side < hi:
                counts[label] += 1
                break
    print(f'\n{split}: total={total}')
    for _, _, label in bins:
        n = counts[label]
        pct = (100*n/total) if total else 0
        print(f'  {label:>7}: {n:5d} ({pct:5.1f}%)')
    if low:
        print(f'  below30={len(low)} min={min(s for s, _ in low)} max_below30={max(s for s, _ in low)}')
        by_ident = {}
        for side, path in low:
            by_ident.setdefault(path.parent.name, 0)
            by_ident[path.parent.name] += 1
        print('  worst identities:')
        for ident, n in sorted(by_ident.items(), key=lambda item: -item[1])[:12]:
            print(f'    {ident}: {n}')
